function startUnitCycle(unitId,part='core'){
 if(unitId!=='custom'&&!UNITS.some(u=>u.id===unitId&&u.id!=='primary-school'))return;
 if(!['core','primary'].includes(part))return;
 const words=unitPartWords(unitId,part);
 if(!words.length){toast('这个范围还没有可学习的词。');return;}
 const previous=state.session;
 const sameCycle=previous?.kind==='unit-cycle'&&previous.unitId===unitId&&unitCyclePart(previous)===part;
 if(previous&&!previous.done){
  if(sameCycle){go('session',true,previous.origin);return;}
  // startSession owns the existing unfinished-correction confirmation.
  if(!(previous.remediation&&!previous.remediation.done)&&!confirm('还有一轮未完成的练习。开始这个范围会结束那一轮，已保存的作答和学习记录仍会保留。是否继续？'))return;
 }
 const items=[];
 for(let offset=0;offset<words.length;offset+=5){
  const group=words.slice(offset,offset+5);
  for(const skill of ['study',...BASIC])for(const word of group)items.push({wordId:word.id,skill});
 }
 const round=sameCycle&&previous.done?(previous.round||1)+1:1;
 const label=part==='primary'?'小学词汇':/^(starter[1-3]|unit[1-7])$/.test(unitId)?'教材单词':'单元循环';
 startSession(items,unitLabel(unitId)+' · '+label+' · 第'+round+'轮','unit-cycle',{manual:true,unitId,unitPart:part,round,origin:sameCycle?previous.origin:routeContext()});
 if(state.session?.id!==previous?.id){
  if(previous){state.sessionHistory??=[];state.sessionHistory.push(structuredClone(previous));}
  if(part==='core')state.selectedUnit=unitId;
  save();
 }
}
