function renderTraining(){const label=view==='memory'?'单词记忆':LABELS[view],words=filteredWords(),available=automaticWords(words).filter(w=>{const r=record(w.id,view==='memory'?'meaning':view);return r.dueAt===null||r.dueAt<=now();}),d=view==='memory'?due('meaning',words):due(view,words);$('#page').innerHTML=heading(learningTrack==='primary'?'预备单元 · '+label:label,({memory:'先认识与理解，再盖住答案主动回忆。',meaning:'看英语辨认中文意思。',listening:'听完整单词的美音，选择中文意思。',dictation:'听完整单词，独立写出英语。',spelling:'看中文释义，独立写出英语。'})[view]||'独立练习这一项能力。')+scopeBar({searchable:true})+`<div class="workspace"><div><section class="panel"><div class="panel-heading"><h2>本轮练习</h2><span class="badge">${available.length} 词可练</span></div><p class="muted">从当前范围练习最多10词。自定义词使用相同题型与复习安排。</p><div class="button-row">${button('开始练习','module-start','primary',available.length?'':'disabled')}${button(`只练到期（${d.length}）`,'module-due','secondary',d.length?'':'disabled')}</div></section><section class="panel"><div class="panel-heading"><h2>学习范围</h2><span class="muted small">${unitLabel(filter)} · ${words.length}词（自动练习${available.length}词）</span></div>${pagedWordTable(words,{answers:false})}<p class="inline-note">可搜索或翻页选择任意词；批量练习跳过100%的词，已掌握词仍可点「手动复习」。</p></section>${sentenceUnitEntry()}</div><aside class="rail"><section class="panel right-note"><h2>这一项单独计分</h2><p>${view==='memory'?'翻卡回忆的自评分记录在翻译辨义。':`${label}的成功不代表其他能力已掌握。`}</p><p>看过答案后立即重做，只算辅助练习。到期后独立答对才延长间隔。</p>${['listening','dictation'].includes(view)?'<p>教材词优先播放预生成的Kokoro美音。同一词固定音色，按教材顺序男女交替；自定义词句使用本机 Kokoro 美音，首次需下载模型；失败时明确提示，可重试或跳过。每题会自动播放，单独按下并松开Ctrl可重播；浏览器阻止自动播放时，可点朗读按钮。无需录音，也不进行发音评分。</p>':''}</section></aside></div>`;}
function strengthBar(w){const value=strength(w);return `<div class="strength-meter" aria-label="记忆强度 ${value}%"><div class="strength-caption"><strong>${value}%</strong><span>${value===100?'已掌握':'记忆强度'}</span></div><progress max="100" value="${value}" aria-label="记忆强度">${value}%</progress></div>`;}
function strengthRules(){return `<details class="strength-rules"><summary>记忆强度怎样计算？</summary><p>每次正常无提示答对，总记忆强度增加10个百分点，最高100%；不再受单项25%的限制。同一天可以多次增加。答错、自评模糊、使用提示或时间经过都不会降低强度。提示、看过答案立即重试和三轮纠错不加分；重复提交同一答案只记录一次。</p><p>原有强度原值保留，不补算历史分数。各能力仍独立安排复习；100%后退出自动复习，仍可手动练习，手动答错也不扣分。100%是软件阈值，不代表永不遗忘。句子听写另存作答记录，不给句中所有单词加分。</p></details>`;}

function wordTable(words,{answers=true,edit=false}={}){return `<div class="table-wrap"><table><thead><tr><th>英语词项</th><th>${answers?'中文释义':'来源'}</th><th>记忆强度</th><th>操作</th></tr></thead><tbody>${words.map(w=>`<tr><td><span class="word-en">${esc(w.english)}</span>${w.status==='custom'?`<p>${esc(w.group)}</p>`:''}</td><td>${answers?esc(w.chinese):esc(unitLabel(w.unitId))}</td><td>${strengthBar(w)}<span class="badge ${mastered(w)?'':'blue'}">${mastered(w)?'已掌握 · 免自动复习':learned(w)?'学习中':'未学'}</span></td><td><div class="row-actions"><button data-practice="${w.id}">${mastered(w)?"手动复习":"练习"}</button>${edit?`${customLearningSkills(w).map(mode=>`<button data-custom-learn="${esc(w.id)}" data-mode="${mode}">${({memory:'记忆',meaning:'翻译',listening:'听辨',dictation:'听写',spelling:'默写'})[mode]}</button>`).join('')}<button data-audio-word="${esc(w.id)}">美音朗读</button>${!w.chinese?'<span class="inline-note">补充中文后解锁翻译、听辨与默写</span>':''}<button data-edit="${w.id}">编辑</button><button data-delete="${w.id}" class="delete">删除</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;}
function sentenceTrackingList(){const words=filteredWords(),info=listPage(words),controls=listPagination(info,'main','句子进度'),slice=info.items;return `<section class="panel" style="margin-top:22px"><div class="panel-heading"><h2>句子进度与手动练习</h2><span>${words.length}句 · ${words.filter(learned).length}已学 · ${words.filter(mastered).length}已掌握</span></div><p class="inline-note">未学句子可从下方开始；手动练习不受30分钟自动复习冷却限制。翻卡记忆记入翻译能力。自定义句子沿用已有学习进度。</p>${controls}${slice.map(w=>`<article class="sentence-row"><p class="word-en">${esc(w.english)}</p><p>${esc(w.chinese||'未添加中文提示')}</p><p class="muted small">${esc(w.group)} · ${esc(w.sourceLabel||'自定义句子')}</p>${strengthBar(w)}<span class="badge">${mastered(w)?'已掌握 · 免自动复习':learned(w)?'学习中':'未学'}</span><div class="button-row">${customLearningSkills(w).map(mode=>`<button class="secondary" data-sentence-track-mode="${mode}" data-sentence-id="${esc(w.id)}">${({memory:'记忆',meaning:'翻译',listening:'听辨',dictation:'听写',spelling:'默写'})[mode]}</button>`).join('')}<button class="secondary" data-audio-word="${esc(w.id)}">美音朗读</button></div>${!w.chinese?'<p class="inline-note">请在自定义句子中补充中文，以解锁翻译、听辨和默写。</p>':''}</article>`).join('')||empty('暂无句子','更换范围或在自定义句子中添加。')}${controls}</section>`;}
function renderTrack(){const sentences=view==='sentence-track',ws=currentWords(),d=due(undefined,ws),n=nextTime(ws);$('#page').innerHTML=heading(sentences?'句子记忆追踪':learningTrack==='primary'?'预备单元 · 记忆追踪':'记忆追踪','各项能力独立排期，只把到期项目加入智能复习。',`<div class="button-row">${button(`复习全部（${d.length}项到期 · 全部能力）`,'review-all','primary',`data-skill="all" ${d.length?'':'disabled'}`)}${button('快速复习（最多10项）','smart-filter','secondary',d.length?'':'disabled')}</div>`)+`<div class="toolbar"><label>记忆追踪范围 <select id="tracking-kind"><option value="words" ${!sentences?'selected':''}>单词能力</option><option value="sentences" ${sentences?'selected':''}>句子能力</option><option value="phrases">固定搭配能力</option></select></label></div>`+scopeBar({searchable:sentences})+`${sentences?'<p class="inline-note">独立新增模块，使用现有50句教材精选／原创拓展与自定义句子；沿用单词记忆规则。旧句子听写记录保留，不补算强度，也不改变句中单词分数。</p>':''}${strengthRules()}<p class="inline-note">无提示答对或完成三轮纠错后，同一${sentences?'句':'词'}至少30分钟后才自动出现；其他未练能力只暂缓，不记作答对。当前范围已掌握（100%）：${ws.filter(mastered).length}${sentences?'句':'词'}，自动复习已跳过。</p>${state.session?.kind==='review-all'&&!state.session.done&&state.session.origin?.view===view&&state.session.origin?.filter===filter&&state.session.origin?.learningTrack===learningTrack?`<div class="resume"><span>全部复习已保存：${state.session.index} / ${state.session.items.length} 项已完成</span>${button('继续全部复习','resume','secondary')}</div>`:''}<div class="skill-grid">${(sentences?BASIC:SKILLS).map(s=>{const rs=ws.filter(w=>!mastered(w)).map(w=>record(w.id,s));return `<section class="skill-card"><div class="panel-heading"><h3>${LABELS[s]}</h3><span class="badge">独立队列</span></div><span class="big">${due(s,ws).length}</span> <span class="muted small">现在到期</span><p>短间隔 ${rs.filter(r=>r.phase==='short').length}项 · 跨天 ${rs.filter(r=>r.phase==='long').length}项${s==='usage'?' · 20词试学范围':''}</p>${button('复习这一项（最多10项）','skill-review','secondary',`data-skill="${s}" ${due(s,ws).length?'':'disabled'}`)} ${button('复习全部这一项','review-all','text-button',`data-skill="${s}" ${due(s,ws).length?'':'disabled'}`)}</section>`;}).join('')}${!sentences?masteredReviewCard(ws):''}</div><section class="panel schedule-panel" id="schedule-panel" style="margin-top:22px"><div class="panel-heading"><h2>接下来的安排</h2><span class="muted small">${n?`最早 ${dateTime(n)}`:'暂时没有未来任务'}</span></div>${scheduleTable(ws)}<p class="inline-note">页面打开时自动更新到期数量，不发送后台提醒。短间隔与跨天安排共用一个调度器。</p></section>${sentences?sentenceTrackingList():''}`;}
const MASTERED_MODES=[['meaning','翻译辨义','看英语，选择正确的中文意思。'],['listening','听力辨义','听完整读音，选择对应的中文意思。'],['dictation','听写','听完整读音，独立写出英语。'],['spelling','默写','看中文释义，独立写出英语。']];
const masteredWords=()=>currentWords().filter(w=>!w.customSentence&&mastered(w));
function masteredReviewCard(words){const count=words.filter(w=>!w.customSentence&&mastered(w)).length;return `<section class="skill-card mastered-card" data-mastered-card><div class="panel-heading"><h3>掌握词复习</h3><span class="badge">自主巩固</span></div><span class="big">${count}</span> <span class="muted small">已掌握单词</span><p>复习当前范围内记忆强度为100%的单词，自选四种练习方式。</p>${button('进入掌握词复习','mastered-review','secondary')}</section>`;}
function renderMasteredReview(){const words=masteredWords(),pending=state.session?.kind==='mastered-review'&&!state.session.done;$('#page').innerHTML=heading(learningTrack==='primary'?'预备单元 · 掌握词复习':'掌握词复习','选择一种方式，复习当前范围内已经掌握的单词。')+scopeBar()+`<section class="panel"><div class="panel-heading"><h2>选择复习方式</h2><span class="badge">${words.length} 个已掌握单词</span></div><p class="inline-note">仅收录记忆强度达到100%的单词，不含句子。每次练习所选范围的全部掌握词，可中途返回并继续；不受自动复习到期或30分钟暂缓限制。既有记忆强度保持100%，学习记录继续保留。</p>${pending?`<div class="resume"><span>已保存：${esc(state.session.title)} · ${state.session.index} / ${state.session.items.length} 项已完成</span>${button('继续掌握词复习','resume','secondary')}</div>`:''}<div class="skill-grid mastered-modes">${MASTERED_MODES.map(([mode,label,description])=>`<section class="skill-card"><h3>${label}</h3><p>${description}</p>${button(label,'mastered-start','primary',`data-mode="${mode}" ${words.some(w=>eligible(w).includes(mode))?'':'disabled'}`)}</section>`).join('')}</div>${!words.length?empty('当前范围还没有掌握词','完成单词练习、记忆强度达到100%后，就能在这里复习；也可以切换学习范围。'):''}</section>`;}
function startMasteredReview(mode){if(!MASTERED_MODES.some(([id])=>id===mode))return;const items=masteredWords().filter(w=>eligible(w).includes(mode)).map(w=>({wordId:w.id,skill:mode}));if(!items.length){toast('当前范围还没有可复习的掌握词。');return;}const previous=state.session;if(previous&&!previous.done){if(previous.kind==='mastered-review'&&previous.origin?.filter===filter&&previous.origin?.learningTrack===learningTrack&&previous.items.every(i=>i.skill===mode)){go('session',true,previous.origin);return;}if(!previous.remediation&&!confirm('还有一轮未完成的练习。开始掌握词复习会结束那一轮，已经保存的作答与学习记录仍会保留。是否继续？'))return;}startSession(items,'掌握词复习 · '+MASTERED_MODES.find(([id])=>id===mode)[1],'mastered-review',{manual:true});if(previous&&!previous.done&&state.session?.id!==previous.id){state.sessionHistory??=[];state.sessionHistory.push(structuredClone(previous));save();}}
const SCHEDULE_PAGE_SIZE=6;
function scheduleTable(ws){const items=ws.filter(w=>!mastered(w)).flatMap(w=>SKILLS.map(s=>({w,s,r:{...record(w.id,s),dueAt:effectiveWordDue(w,record(w.id,s))}}))).filter(x=>x.r.dueAt!==null).sort((a,b)=>a.r.dueAt-b.r.dueAt);const info=listPage(items,'schedule',SCHEDULE_PAGE_SIZE),controls=listPagination(info,'schedule','复习安排'),visible=info.items;return items.length?`${controls}<div class="table-wrap schedule-table" tabindex="0" aria-label="本页复习安排，可滚动查看"><table><thead><tr><th>${view==='sentence-track'?'句子':'词项'}</th><th>能力</th><th>记忆强度</th><th>复习层次</th><th>下次复习</th></tr></thead><tbody>${visible.map(({w,s,r})=>`<tr data-schedule-word="${esc(w.id)}" data-schedule-skill="${s}"><td class="word-en">${esc(w.english)}</td><td>${LABELS[s]}${state.records[w.id]?.legacy?'<p>含旧版综合兼容记录</p>':''}</td><td>${strengthBar(w)}</td><td>${r.phase==='short'?'课内短间隔':'跨天巩固'}</td><td>${dueText(r)}<p>${dateTime(r.dueAt)}</p></td></tr>`).join('')}</tbody></table></div>${controls}`:`${controls}${empty('当前没有自动复习安排',view==='sentence-track'?'在下方选择句子开始练习；100%的句子已免自动复习，仍可手动练习。':'尚未学习的词可开始新课；100%的词已免自动复习，仍可手动练习。')}`;}
function renderMistakes(){const items=wrong(skillFilter==='all'?undefined:skillFilter,currentWords()),dueWrong=items.filter(itemDue),info=listPage(items),controls=listPagination(info,'main','错词');$('#page').innerHTML=heading(learningTrack==='primary'?'预备单元 · 错词本':'错词本','错误按能力分别记录；到期后两次独立成功，才会移出。')+scopeBar()+`<div class="toolbar"><label>能力 <select id="skill-filter"><option value="all">全部能力</option>${SKILLS.map(s=>`<option value="${s}" ${skillFilter===s?'selected':''}>${LABELS[s]}</option>`).join('')}</select></label>${button(`复习到期错词（${dueWrong.length}）`,'mistakes-due','primary',dueWrong.length?'':'disabled')}${button('提前巩固','mistakes-all','secondary',items.length?'':'disabled')}</div>${items.length?`<section class="panel"><p class="count-summary">${items.length}项待巩固。提前练习不增加记忆强度；30分钟暂缓只适用于记忆追踪，不影响本页练习。</p>${controls}<div class="table-wrap"><table><thead><tr><th>${view==='sentence-track'?'句子':'词项'}</th><th>能力</th><th>错误次数</th><th>复习安排</th></tr></thead><tbody>${info.items.map(i=>`<tr><td class="word-en">${esc(wordById(i.wordId).english)}</td><td>${LABELS[i.skill]}</td><td>${i.record.lapses}</td><td>${wordDueText(wordById(i.wordId),i.record)}</td></tr>`).join('')}</tbody></table></div>${controls}</section>`:empty('错词本现在是空的','答错的词会自动归入对应能力，逐步练熟即可。')}`;}
function startSession(items,title,kind='practice',{manual=false,unitId=null,unitPart='core',round=1,origin=null}={}){if(view==='sentence-center'&&state.session&&!state.session.done){toast('先继续或完成已保存的练习，再开始新的句子练习。');go('session',true,state.session.origin||null);return;}stopAudio();items=items.filter(i=>{const w=wordById(i.wordId);return w&&(i.skill==='study'||i.skill==='memory'||eligible(w).includes(i.skill));}).map(i=>i.skill==='memory'&&!wordById(i.wordId).chinese?{...i,skill:'study'}:i);if(state.session?.remediation&&!state.session.remediation.done&&!confirm('还有未完成的三轮纠错。开始新练习会结束当前纠错，但保留错误记录和复习安排。是否继续？'))return;const cooldownPolicy=!manual&&kind!=='lesson'&&trackingView()?'tracking':'none';if(!manual)items=items.filter(i=>!mastered(wordById(i.wordId))&&(cooldownPolicy!=='tracking'||!cooling(wordById(i.wordId)))&&(kind==='lesson'||record(i.wordId,i.skill==='memory'?'meaning':i.skill).dueAt===null||record(i.wordId,i.skill==='memory'?'meaning':i.skill).dueAt<=now()));if(learningTrack==='primary'&&!title.startsWith('预备单元'))title='预备单元 · '+title;if(filter==='all-tracks')title='全站复习 · '+title;if(!items.length){toast('当前没有可练项目。');return;}state.session={id:crypto.randomUUID(),origin:origin||routeContext(),items,index:0,title,kind,...(kind==='unit-cycle'?{unitId,unitPart,round}:{}),manual,cooldownPolicy,queuePolicyVersion:2,masterySkipped:0,cooldownSkipped:0,attemptNo:0,result:null,draft:'',practiceOnly:false,startedAt:now(),done:false};save();go('session');}
function startAllDue(skill='all'){const existing=state.session;if(existing?.kind==='review-all'&&!existing.done&&existing.origin?.view===view&&existing.origin?.filter===filter&&existing.origin?.learningTrack===learningTrack&&existing.reviewSkill===skill){go('session');return;}const items=[...new Map(due(skill==='all'?undefined:skill,currentWords()).map(i=>[i.wordId+':'+i.skill,{wordId:i.wordId,skill:i.skill}])).values()];if(!items.length){toast('当前范围没有到期项目。');return;}startSession(items,`复习全部 · ${skill==='all'?'全部能力':LABELS[skill]} · ${items.length}项`,'review-all');state.session.reviewSkill=skill;save();}
function startNewLesson(){const ws=automaticWords(selectedWords()).filter(w=>!learned(w)).slice(0,5);startSession(['study',...BASIC].flatMap(skill=>ws.map(w=>({wordId:w.id,skill}))),`${unitLabel(state.selectedUnit)} · 新课学习`,'lesson');}
function sortedPractice(ws){return automaticWords(ws).filter(w=>{const r=record(w.id,view==='memory'?'meaning':view);return r.dueAt===null||r.dueAt<=now();}).sort((a,b)=>Number(learned(a))-Number(learned(b)));}
function currentItem(){return state.session?.items[state.session.index];}
