function playCorrectionWord({automatic=false}={}){const s=state.session,r=s?.remediation;if(!r||r.paused||r.done)return;const key=correctionKey(),w=wordById(r.wordId),entry=recordedAudio.get(r.wordId);stopAudio();correctionAutoKey=key;if(r.step>0&&$('#correction-submit'))$('#correction-submit').disabled=true;const active=()=>view==='session'&&correctionKey()===key&&!state.session?.remediation?.paused;const status=()=>$('#correction-audio-status');const update=text=>{if(active()&&status())status().textContent=text;};const options={retry:!automatic,onLoading:update,onStart:()=>update('正在播放 Kokoro 合成美音。'),onComplete:()=>{if(!active())return;correctionListenReady=true;update('整词播放完成，可以核对拼写。');const b=$('#correction-submit');if(b&&!state.session.remediation.feedback)b.disabled=false;},onError:message=>{if(!active())return;update(message);if(status()){const retry=document.createElement('button');retry.className='text-button';retry.textContent='重试整词朗读';retry.onclick=()=>playCorrectionWord();status().append(document.createElement('br'),retry);}}};if(entry)player.playFile(new URL('../'+entry.file,import.meta.url).href,options);else customKokoro.play(w.english,{...options,id:w.id});}
