function audioHTML(w){const e=recordedAudio.get(w.id),label=e?`Kokoro · ${e.voice==='sentence'?'整句录音':e.voice==='af_heart'?'女声':'男声'} · 美音`:customKokoroLabel(w.id);return `<button class="audio-button" data-action="audio">◖)) ${w.customSentence?'整句':'整词'}朗读</button><p class="audio-source">${label}${e?'':w.status==='custom'?' · 首次需下载模型，生成后本机缓存':' · 此词暂无预生成音频'}</p>${['listening','dictation'].includes(currentItem()?.skill)?'<p class="audio-shortcut">每题自动播放 · 单独按下并松开 Ctrl 可重播</p>':currentItem()?.skill==='study'&&!w.customSentence?'<p class="audio-shortcut">切到新词自动朗读一次 · 想再听可点「整词朗读」</p>':''}<div id="speech-notice" class="notice" hidden role="status"></div>`;}
