 if(stage==='usage'){const e=pilotById.get(w.id),q=e.exercises.find(q=>q.id===(currentItem().questionId||state.session.questionId))||e.exercises[Math.max(0,record(w.id,'usage').reviews-(state.session.replay?1:0))%e.exercises.length];if(state.session.questionId!==q.id||currentItem().questionId!==q.id){state.session.questionId=q.id;currentItem().questionId=q.id;save();}return `${usageAudioHTML(q)}<p class="reading-text">${esc(q.context)}</p><p>${esc(q.prompt)}</p><div class="choices">${q.choices.map(c=>`<button class="choice ${res&&c.id===q.correctChoiceId?'correct':''}" data-usage-choice="${c.id}" ${res?'disabled':''}>${esc(c.text)}</button>`).join('')}</div>`;}
 return `${stage==='dictation'?audioHTML(w):`<div class="meaning">${esc(w.chinese)}</div>${audioHTML(w)}`}<p class="muted">${stage==='dictation'?'听完后，输入完整单词、短语或句子。':`看中文，写出完整英语。${w.caseSensitive?'注意大小写区分词义。':''}`}</p>${res?.correct===false?spellingDiffHTML(w,res.input??state.session.draft,esc):''}<form id="spell-form" class="spell-form"><label for="spell-input">英语答案</label><input id="spell-input" lang="en" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="500" ${res?'disabled':''}>${res?'':`<button class="primary" id="check-answer" ${stage==='dictation'&&!listenReady?'disabled':''}>核对答案</button>`}</form>${res?'':button('查看提示','hint','text-button')}${state.session.hint?memoryHTML(w):''}`;
