function feedbackHTML(w,res){return `<div data-answer-result="${res.skip?'neutral':res.correct?'correct':'incorrect'}" class="feedback ${res.correct||res.skip?'':'wrong'}" role="status" aria-live="polite"><strong class="feedback-title">${res.skip?'本题已跳过':res.rating==='hard'?'仍需巩固':res.correct?'答对了':'查看正确答案'}</strong>${res.skip?'<p>没有计错，也没有记录成功。</p>':`<p><span class="word-en">${esc(w.english)}</span> · ${esc(w.chinese)}</p><p>${res.explanation?esc(res.explanation):''}</p><p>${state.session?.replay?'本次为再学一遍，保留原有强度与复习日期，不重复计入独立成功。':res.assisted?(res.assistanceReason==='retry'?'这是刚看过答案后的纠错重练，不增加独立成功。':res.assistanceReason==='audio'?'本题使用了答案语音提示，作为辅助练习，不增加独立成功。':res.assistanceReason==='hint'?'本题使用了记忆提示，作为辅助练习，不增加独立成功。':'这是此前保存的辅助练习结果；新的作答按本题提示使用情况判断。'):!res.correct?(mastered(w)?'本次错误已记录，强度保持100%，不加入自动复习。':`本次错误已记录，记忆强度不降低；${state.settings.steps[0]}分钟后重新到期。`):res.rating==='hard'?'本次自评模糊，已保留短间隔巩固。':mastered(w)?'记忆强度达到100%，已停止自动复习；仍可手动练习。':res.firstStrengthCredit?'本项能力首次独立答对，记忆强度已增加；后续仍按原日期复习。':res.ordinaryStrengthCredit?'本次独立答对，记忆强度已增加；原复习排期保留。':res.accepted?`独立回忆已记录，下次${wordDueText(w,res.record)}。`:'这次是提前巩固，强度不重复增加；原能力排期保留。30分钟同词暂缓只用于记忆追踪。'}</p>${res.strengthChange?.delta?`<p class="strength-change">记忆强度：${res.strengthChange.before}% → ${res.strengthChange.after}%（${res.strengthChange.delta>0?'+':''}${res.strengthChange.delta}%）</p>`:res.correct&&res.strengthChange?.reason==='total-cap'?'<p class="inline-note">记忆强度已达到100%。</p>':''}`}</div>`;}
function cancelCorrectAdvance(){if(correctAdvanceTimer===null)return;window.clearTimeout(correctAdvanceTimer);correctAdvanceTimer=null;}
function queueCorrectAdvance(session,index,result){
 cancelCorrectAdvance();
 // Acknowledgment remains visible briefly; only this newly answered card may advance.
 correctAdvanceTimer=window.setTimeout(()=>{
  correctAdvanceTimer=null;
  if(view==='session'&&!document.hidden&&!document.querySelector('dialog[open]')&&state.session===session&&session.index===index&&session.result===result&&!session.done&&!session.remediation)advance();
 },650);
}
function answer(correct,extra={}){const session=state.session;if(session.result)return;const item=currentItem(),w=wordById(item.wordId),out=scoreItem(correct?'good':'again');const result=session.result={correct,...out,...extra},index=session.index;if(!correct&&['dictation','spelling'].includes(item.skill))session.remediation={...freshCorrection(w.id,now()),initialInput:extra.input??session.draft};state.exposure[w.id]=now()+state.settings.steps[0]*MINUTE;save();render();if(correct&&BASIC.includes(item.skill))queueCorrectAdvance(session,index,result);}
function advance(){stopAudio();const s=state.session;if(!s||s.done||s.remediation&&!s.remediation.done)return;s.remediation=null;if(currentItem().skill==='study'){if(!s.replay)introduce(wordById(currentItem().wordId));}else if(!s.result)return;s.index++;s.attemptNo=0;s.result=null;s.draft='';s.hint=false;s.hintReason=null;s.revealed=false;s.practiceOnly=!!s.replay;s.questionId=null;s.exposedItem=null;s.done=s.index>=s.items.length;listenReady=false;save();render();}
function audioContext(){const item=currentItem();return state.session&&item?`${state.session.id}:${state.session.index}:${item.skill}:${item.wordId}`:null;}
function sessionAudioAvailable(){return view==='session'&&!document.hidden&&!document.querySelector('dialog[open]')&&!state.session?.done&&!state.session?.remediation?.paused&&!state.session?.remediation?.done;}
function replayEnabled(){return sessionAudioAvailable()&&['listening','dictation'].includes(currentItem()?.skill)&&!!wordById(currentItem()?.wordId);}
function prepareCurrentAudio(){const item=currentItem();if(!item)return;if(item.skill==='usage'){const spec=contextAudioSpec(currentUsageQuestion());if(spec.file)player.prefetchFile(spec.file).catch(()=>{});return;}const entry=recordedAudio.get(item.wordId);if(entry)player.prefetchFile(new URL('../'+entry.file,import.meta.url).href).catch(()=>{});}
function autoPlayCurrentQuestion(){prepareCurrentAudio();const next=state.session?.items[state.session.index+1],nextAudio=next?.skill!=='usage'&&recordedAudio.get(next?.wordId);if(nextAudio)player.prefetchFile(new URL('../'+nextAudio.file,import.meta.url).href).catch(()=>{});const item=currentItem(),word=wordById(item?.wordId);if(!word||!sessionAudioAvailable()||state.session.result)return;const studyWord=item.skill==='study'&&!word.customSentence;if(!studyWord&&!replayEnabled())return;const key=audioContext();if(autoPlayedKey===key)return;autoPlayedKey=key;playAudio(word,{automatic:true});}
function playAudio(w,{assessment=true,automatic=false}={}){
 customKokoro.stop();
 if(view==='session'&&state.session?.remediation){playCorrectionWord({automatic});return;}
 if(view==='session'&&currentItem()?.skill==='usage'){playContextSentence();return;}
 const context=assessment&&view==='session'?`${state.session?.id}:${state.session?.index}:${currentItem()?.skill}:${w.id}`:null;
 const stillCurrent=()=>context&&view==='session'&&`${state.session?.id}:${state.session?.index}:${currentItem()?.skill}:${currentItem()?.wordId}`===context;
 const listening=context&&['listening','dictation'].includes(currentItem()?.skill);
 if(listening){listenReady=false;document.querySelectorAll('[data-choice],#check-answer').forEach(b=>b.disabled=true);}
 // Hearing the answer is a hint during written recall or context fill-in.
 if(context&&currentItem()?.skill==='spelling'&&!state.session.result){state.session.hint=true;state.session.hintReason='audio';expose(w);}
 const complete=()=>{if(stillCurrent()){listenReady=true;document.querySelectorAll('[data-choice],#check-answer').forEach(b=>{if(!state.session.result)b.disabled=false;});}};
 const error=message=>{if(context&&!stillCurrent())return;listenReady=false;const e=$('#speech-notice')||$('#page-audio-notice');if(e){e.textContent=message;e.hidden=false;if(w){const retry=document.createElement('button');retry.className='text-button';retry.dataset.audioKokoroRetry='true';retry.textContent='重试 Kokoro 美音';retry.onclick=()=>playAudio(w,{assessment});e.append(document.createElement('br'),retry);}}else toast(message);};
 const loading=message=>{if(context&&!stillCurrent())return;const e=$('#speech-notice')||$('#page-audio-notice');if(e){e.textContent=message;e.hidden=false;}};
 const started=()=>{if(context&&!stillCurrent())return;const e=$('#speech-notice')||$('#page-audio-notice');if(e)e.hidden=true;};
 const recorded=recordedAudio.get(w.id),sourceLabel=$('.audio-source');if(sourceLabel&&context)sourceLabel.textContent=recorded?`Kokoro · ${recorded.voice==='sentence'?'整句录音':recorded.voice==='af_heart'?'女声':'男声'} · 美音`:customKokoroLabel(w.id);
 if(recorded)player.playFile(new URL('../'+recorded.file,import.meta.url).href,{onComplete:complete,onError:error,onStart:started,onLoading:loading,retry:!automatic});
 else customKokoro.play(w.english,{id:w.id,onComplete:complete,onError:error,onStart:started,onLoading:loading,retry:!automatic});
}
function bindSession(){const s=state.session;const spellInput=$('#spell-input');const syncDraft=()=>{spellInput.setCustomValidity('');s.draft=spellInput.value;save();};spellInput?.addEventListener('input',syncDraft);spellInput?.addEventListener('change',syncDraft);$('#spell-form')?.addEventListener('submit',e=>{e.preventDefault();if(s.result||currentItem().skill==='dictation'&&!listenReady)return;const input=$('#spell-input');if(!input.value.trim()){input.setCustomValidity('请先输入答案。');input.reportValidity();return;}input.setCustomValidity('');answer(customAnswerCorrect(wordById(currentItem().wordId),input.value),{input:input.value});});document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{if(currentItem().skill==='listening'&&!listenReady)return;answer(b.dataset.choice===wordById(currentItem().wordId).chinese,{choice:b.dataset.choice});}));document.querySelectorAll('[data-usage-choice]').forEach(b=>b.addEventListener('click',()=>{const q=pilotById.get(currentItem().wordId).exercises.find(q=>q.id===s.questionId);answer(b.dataset.usageChoice===q.correctChoiceId,{explanation:q.explanationZh});}));}
function filteredWords(){return currentWords().filter(w=>!search||`${w.english} ${w.chinese} ${w.group||''}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));}
