function openCustomSentences(id=null){customManagerOrigin=routeContext();state.sentenceDictation??={items:{}};if(id){const item=state.sentenceDictation.customSentences?.find(x=>x.id===id);state.sentenceDictation.customDraft={...item,editingId:id,manual:true,translatedEnglish:item?.english||''};}sentenceManaging=false;go('custom-sentences');}
function startCustomLearning(id,mode){const ws=id?[wordById(id)].filter(Boolean):allCustomWords().filter(w=>(filter==='all'||filter===w.group)&&(!search||`${w.english} ${w.chinese} ${w.group}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())));const items=ws.flatMap(w=>(mode==='all'?['study',...customLearningSkills(w).filter(x=>x!=='memory')]:customLearningSkills(w).includes(mode)?[mode]:[]).map(skill=>({wordId:w.id,skill})));startSession(items,`自定义词句 · ${{all:'完整学习',memory:'记忆',meaning:'翻译',listening:'听辨',dictation:'听写',spelling:'默写'}[mode]||'学习'}`,'practice',{manual:true});}
function listPage(items,key='main',size=6){const info=pageSlice(items,key==='schedule'?schedulePage:key==='context-custom'?contextCustomPage:page,size);if(key==='schedule')schedulePage=info.page;else if(key==='context-custom')contextCustomPage=info.page;else page=info.page;return info;}
