function renderReading(){if(view==='cloze'&&readingScope!=='custom'){renderClozeReference();return;}if(readingScope==='custom'){renderCustomReading();return;}const p=PILOT.passages[passageIndex],cloze=view==='cloze',qs=cloze?p.clozeQuestions:p.readingQuestions;if(!cloze){p.targetWordIds.forEach(id=>state.exposure[id]=now()+state.settings.steps[0]*MINUTE);save();}$('#page').innerHTML=heading(cloze?'完形填空':'阅读理解',cloze?'用上下文选择合适词语，提交后查看句内线索与解释。':'先读短文，再依据原文回答问题。')+`<div class="toolbar"><label>内容范围 <select id="reading-source"><option value="pilot">教材词试学</option><option value="custom">自定义词</option></select></label><label>原创短文 <select id="passage-select">${PILOT.passages.map((p,i)=>`<option value="${i}" ${passageIndex===i?'selected':''}>${esc(p.title)} · ${p.wordCount}词</option>`).join('')}</select></label><span class="badge blue">2篇短文 · 试学</span></div><div class="reading-layout"><article class="panel"><h2>${esc(p.title)}</h2><p class="coverage-label">${cloze?'下面为保留空缺的短文；提交后再看该题原句。':'原创短文，采用短句与受控语言；不是教材原文。'}</p><p class="reading-text">${esc(cloze?qs.reduce((t,q)=>t.replace(q.sentence,q.blankedSentence),p.text):p.text)}</p>${!cloze?`<details id="reading-translation"><summary>查看中文译文</summary><p class="muted" style="margin-top:15px">${esc(p.translationZh)}</p></details>`:''}<div class="button-row" style="margin-top:20px">${button('句子结构讲解','analysis-nav','secondary')}</div></article><section class="panel"><h2>${cloze?'结合上下文填空':'原文理解'}</h2>${qs.map(questionHTML).join('')}</section></div><p class="inline-note">阅读理解记录题目完成情况，不把整篇答对当成所有单词都已掌握。完形中有明确目标词的题目进入该词的语境能力安排。</p>`;bindQuestions();}
function playPracticeText(text,status,{file=null,customId=null}={}){stopAudio();const update=message=>{if(status?.isConnected)status.textContent=message;};const handlers={retry:true,onLoading:update,onStart:()=>update('正在播放 Kokoro 合成美音，可点击停止或重播。'),onComplete:()=>update('朗读结束，可以重播并跟读。'),onError:message=>{update(message+' 可重试；不影响文字练习。');if(status?.isConnected){const retry=document.createElement('button');retry.className='text-button';retry.dataset.audioKokoroRetry='true';retry.textContent='重试 Kokoro 美音';retry.onclick=()=>playPracticeText(text,status,{file,customId});status.append(document.createElement('br'),retry);}}};if(file)player.playFile(file,handlers);else customKokoro.play(text,{...handlers,id:customId||'text:'+text});}
function renderClozeReference(){const groups=[...new Map(ADAPTIVE_BANK.questions.filter(q=>q.module==='cloze').map(q=>[q.passageId||q.title,q])).values()];const info=listPage(groups),controls=listPagination(info,'main','完形短文');const seen=state.adaptive?.modules?.cloze?.seen||[];$('#page').innerHTML=heading('完形填空 · 短文资料','与阅读理解使用独立短文。完成同篇所有空格的作答后，才解锁完整原文与朗读。')+`<div class="toolbar"><label>内容范围 <select id="reading-source"><option value="pilot">原创完形资料</option><option value="custom">自定义词</option></select></label></div>`+controls+info.items.map(q=>{const qs=ADAPTIVE_BANK.questions.filter(x=>x.module==='cloze'&&(x.passageId||x.title)===(q.passageId||q.title)),ready=qs.every(x=>seen.includes(x.id));return `<section class="panel"><h2>${esc(q.title)}</h2>${ready?`<p class="reading-text">${esc(q.completedPassage)}</p><button class="secondary" data-practice-passage="${esc(q.id)}">朗读全文 / 重播</button> <button class="secondary" data-practice-stop>停止</button><p class="inline-note" data-practice-status role="status">作答已完成，可以听音跟读。</p>`:`<p class="muted">已作答 ${qs.filter(x=>seen.includes(x.id)).length} / ${qs.length} 个空。全文及朗读将在整篇作答后显示。</p>`}</section>`;}).join('')+controls;document.querySelectorAll('[data-practice-passage]').forEach(b=>b.onclick=()=>{const q=ADAPTIVE_BANK.questions.find(q=>q.id===b.dataset.practicePassage);playPracticeText(q.completedPassage,b.parentElement.querySelector('[data-practice-status]'),{file:q.audioFile});});document.querySelectorAll('[data-practice-stop]').forEach(b=>b.onclick=()=>{stopAudio();b.parentElement.querySelector('[data-practice-status]').textContent='已停止。';});}
function renderAnalysis(){const a=PILOT.sentenceWalkthroughs[passageIndex];$('#page').innerHTML=heading('句子讲解','从主干、时间和原因部分看懂句子；当前提供2句结构试学。')+`<div class="toolbar"><label>例句 <select id="passage-select">${PILOT.sentenceWalkthroughs.map((s,i)=>`<option value="${i}" ${passageIndex===i?'selected':''}>${i+1}. ${esc(PILOT.passages[i].title)}</option>`).join('')}</select></label><span class="badge blue">基础复合句 · 非全量长难句课程</span></div><div class="reading-layout"><article class="panel"><p class="reading-text">${esc(a.sentence)}</p><button class="secondary" id="legacy-sentence-audio">朗读例句 / 重播</button> <button class="secondary" id="legacy-sentence-stop">停止</button><p class="inline-note" id="legacy-sentence-status" role="status">整句跟读；只朗读英文例句。</p><p class="muted">${esc(a.meaningZh)}</p>${a.chunks.map(c=>`<div class="analysis-chunk"><strong>${esc(c.text)}</strong><p>${esc(c.roleZh)}</p><p class="muted">${esc(c.meaningZh)}</p></div>`).join('')}</article><aside><section class="panel"><h2>抓住主干</h2><p>${esc(a.mainMessageZh)}</p><h2>连接词怎样起作用</h2><p>${esc(a.connectorExplanationZh)}</p></section><section class="panel"><h2>检查理解</h2>${questionHTML(a.checkQuestion)}</section></aside></div>`;bindQuestions();player.prefetchFile(PRACTICE_AUDIO.legacySentenceFiles[a.id]).catch(()=>{});$('#legacy-sentence-audio').onclick=()=>playPracticeText(a.sentence,$('#legacy-sentence-status'),{file:PRACTICE_AUDIO.legacySentenceFiles[a.id]});$('#legacy-sentence-stop').onclick=()=>{stopAudio();$('#legacy-sentence-status').textContent='已停止。';};}
function renderCustomReading(){$('#page').innerHTML=heading(view==='cloze'?'完形填空':'阅读理解','自定义词内容状态')+`<div class="toolbar"><label>内容范围 <select id="reading-source"><option value="pilot">教材词试学</option><option value="custom" selected>自定义词</option></select></label></div><section class="panel"><h2>自定义词的短文内容尚未编写</h2><p>添加单词会立即进入基础训练、错词与记忆追踪；不会自动编造包含这些词的阅读篇章。你添加的英文例句可在搭配与语境中回填训练。</p>${custom.length?pagedWordTable(custom,{edit:true}):'<p class="muted">还没有自定义词。</p>'}${button('进入自定义例句','custom-context','secondary')}</section>`;}
function bindQuestions(){document.querySelectorAll('[data-question-choice]').forEach(b=>b.addEventListener('click',()=>{const q=allQuestions().find(q=>q.id===b.dataset.questionChoice);if(state.results[q.id])return;const correct=b.dataset.choiceId===q.correctChoiceId,previous=!!state.dailyQuestionSeen?.[q.id];state.results[q.id]={choice:b.dataset.choiceId,correct,at:now()};state.dailyQuestionSeen??={};state.dailyQuestionSeen[q.id]=true;
trackLearning({id:'reference:'+crypto.randomUUID(),at:state.results[q.id].at,mode:['context','reading','cloze','analysis'].includes(view)?view:'usage',itemId:q.id,label:q.question||q.blankedSentence||q.context||q.prompt||q.id,kind:previous?'correction':'answer',first:!previous,assisted:previous,correct,completed:previous&&correct});if(q.wordId&&wordById(q.wordId)){const priorStrength=strengthState(wordById(q.wordId));const out=schedule(record(q.wordId,'usage'),correct?'good':'again',now(),{assisted:state.exposure[q.wordId]>now(),steps:state.settings.steps});const strengthUpdate=applyStrength(priorStrength,{id:'reference:'+crypto.randomUUID(),skill:'usage',rating:correct?'good':'again',independent:out.independent,at:now()});state.memoryStrength[q.wordId]=strengthUpdate.state;if(correct&&out.independent)markRest(wordById(q.wordId));else if(!correct)delete state.autoCooldown[q.wordId];setRecord(q.wordId,'usage',out.record);state.exposure[q.wordId]=now()+state.settings.steps[0]*MINUTE;}save();render();}));}
function settings(){stopAudio();practiceTimer.setEligible(false);const d=$('#settings-dialog');d.innerHTML=`<div class="dialog-heading"><h2 id="settings-title">设置与来源</h2><button class="close" data-close="settings-dialog" aria-label="关闭">×</button></div>${BACKUP_SECTION}<h3>记忆强度</h3>${strengthRules()}<h3>间隔复习规则</h3><p>参考遗忘规律安排间隔，不把它当作个人遗忘曲线的精确测量。只有记忆追踪使用同词至少30分钟的暂缓；任务中心新课按既定步骤连续完成，其他练习不套用这项暂缓。记忆追踪之后遵循各能力到期日，跨天间隔按1、3、7、14、30、60天递增。手动点词练习不受这段自动暂停限制。</p><h3>双层复习规则</h3><p>每个词的翻译、听力、听写、默写、语境分别记录。不会或模糊时回到短间隔；短间隔中的两次到期独立成功后进入跨天复习。跨天成功逐步延长至1、3、7、14、30、60天。</p><p>这是可解释的产品安排，借鉴间隔练习与主动回忆，不是对个人遗忘的精确测量，也不保证记牢。</p><form id="steps-form"><div class="toolbar"><label>短间隔 <select name="steps"><option value="1,5" ${state.settings.steps[0]===1?'selected':''}>1分钟 / 5分钟（默认）</option><option value="2,10" ${state.settings.steps[0]===2?'selected':''}>2分钟 / 10分钟</option><option value="5,20" ${state.settings.steps[0]===5?'selected':''}>5分钟 / 20分钟</option></select></label><button class="secondary">保存间隔</button></div></form><p class="inline-note">修改只影响今后的评分，已经安排的日期不变。提示、立即抄答案和提前练习不增加独立成功。</p><h3>教材覆盖</h3><p>${esc(BOOK.title)} · ${esc(BOOK.edition)}。现含单元词表${BOOK.originalUnitWords}词项，以及小学词汇、数词、月份、星期${BOOK.supplementalCount}词项，共${BOOK.totalWords}词项；其他年级未接入。</p><p>${esc(BOOK.verification||'')}</p><a href="${esc(BOOK.source)}" target="_blank" rel="noopener">查看官方教材来源</a><h3>拼读与语境覆盖</h3><p>20词有核对后的美音IPA、读音音节和独立的拼写教学块；原有20词语境资料与2篇阅读资料保留。搭配与语境、阅读理解、完形填空、句子讲解各128道原创题，共512道、16个知识点，每个知识点32题。阅读为32篇短文，每篇4道不同考点题连续完成后再换新篇；完形为128篇独立迷你短文，每篇1空，与阅读不共用材料。旧题ID和学习记录保留。答错后连续独立答对2道新题才完成本轮巩固；只选择未见新场景，同篇阅读不在后续新组重复；全部可用内容耗尽会明确提示，不会重出旧题或声称无限生成。不是全部词项的系统语境课程，也不是独立教师审定。</p><p>当前21个已核对词项提供音节分析与Kokoro合成分读（未人工听审），其余词项使用整词纠错，不自动猜分音节。未实现任意新词的自动可靠音节切分。教材词使用预生成的Kokoro美音，女声af_heart、男声am_michael交替；原289词的声音保持不变；同一词重播与跨模块保持同一音色。Kokoro是合成声音，不是真人录音；音频通过解码、静音和削波检查，但尚未逐条听审。句子讲解和完形全文使用预生成或本机合成的Kokoro美音；新增内容按需在本机合成，完形先作答后解锁。合成音已做解码和电平检查，未逐条人工听审。自定义单词和句子使用本机 Kokoro 合成美音，af_heart 与 am_michael 按新增条目交替并固定音色。首次需下载较大的模型，合成结果缓存在当前浏览器；英文改变会生成新音频。不向语音服务器上传自定义文本。加载或生成失败会明确提示，不会冒充 Kokoro 自动切换设备声音；所有朗读入口均使用 Kokoro 美音，不再提供设备声音后备。</p><p><a href="audio/LICENSE.txt" target="_blank" rel="noopener">原录音模型与许可说明</a> · <a href="vendor/kokoro/PROVENANCE.md" target="_blank" rel="noopener">本机 Kokoro 运行库与许可</a></p><h3>自动中文匹配</h3><p>优先使用教材释义，再查ECDICT通用英汉词典。只做精确词项与词典明确词形匹配，不猜测未知词；多义项请按语境检查。通用数据由ECDICT汇总，未对全部上游来源与释义逐条审定。</p><p><a href="https://github.com/skywind3000/ECDICT" target="_blank" rel="noopener">ECDICT来源</a> · <a href="dictionary/LICENSE.txt" target="_blank" rel="noopener">MIT许可</a></p><h3>学习记录</h3><p>必须登录账户后使用。每个账号拥有独立的 Supabase 云端进度，学习记录不会保存到浏览器；页面显示“云端已保存”后才表示本次变化已经写入账号。JSON 文件可用于手动导出和恢复。旧版只有综合记录，无法可靠推断具体能力；兼容记录暂由翻译队列承接，这不是翻译掌握证据，其他能力不会被标为已掌握。</p><h3>引用与教学说明</h3><p>${esc(PILOT.metadata.boundaryPolicyZh)}</p><button class="danger-button" id="clear-progress">清空本机学习进度</button>${PILOT.sources.slice(0,4).map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a></p>`).join('')}<p><a href="https://www.learningscientists.org/blog/2022/8/18-1" target="_blank" rel="noopener">间隔练习与提取练习</a></p>`;d.showModal();bindBackupUI({dialog:d,storage,flush:()=>{if(blocked||customDamaged||phraseLoaded.blocked||!learningLedger.snapshot().available)throw Error('本机存在未保存或无法读取的记录，暂不能备份或导入。请先检查浏览器存储。');if(!save()||!savePhrase())throw Error('当前学习进度尚未保存，未继续操作。');},pause:()=>{stopAudio();practiceTimer.setVisible(false);},resume:()=>{practiceTimer=createPracticeTimer({storage,wallNow:now,monoNow:()=>performance.now(),tabId:crypto.randomUUID()});practiceTimer.setVisible(!document.hidden);},stop:()=>{stopAudio();practiceTimer.stop();},validateReferences:records=>{const ws=records['word-garden.workspace.v2']||{},cs=records['word-garden.custom.v1']?.words||[],ph=records['word-garden.phrases.v1'];validateStorageRecords(records,{adaptiveQuestionIds:new Set([...ADAPTIVE_BANK.questions,...(ADAPTIVE_BANK.archivedQuestions||[])].map(q=>q.id)),wordIds:new Set([...BASE,...BUILTIN_SENTENCES,...customLearningWords(cs,ws)].map(w=>w.id)),phraseIds:new Set([...PHRASE_BANK.entries,...(ph?.custom||[])].map(p=>p.id))});}});$('#clear-progress').addEventListener('click',()=>{if(!confirm('确定清空单词学习进度、错词和星星吗？自定义词、应用练习的出题与讲解记录保留，避免重出旧题。单词学习记录无法撤销。'))return;state={...state,autoCooldown:{},memoryStrength:{},records:{},exposure:{},stars:0,session:null,results:{},adaptive:state.adaptive||freshPractice()};save();d.close();go('tasks');toast('单词学习进度已清空；自定义词和应用题出题历史仍保留。');});$('#steps-form').addEventListener('submit',e=>{e.preventDefault();state.settings.steps=new FormData(e.target).get('steps').split(',').map(Number);save();toast('今后的短间隔已更新。');render();});bindClose();}
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).close()));}
function bindCommon(){bindPagination($('#page'),{keys:['main','schedule','context-custom'],onChange:(key,next)=>{stopAudio();if(key==='schedule')schedulePage=next;else if(key==='context-custom')contextCustomPage=next;else page=next;render();history.replaceState({view,context:routeContext()},'',`#${routeHash(view)}`);focusPagination($('#page'),key);}});document.querySelectorAll('[data-sentence-unit]').forEach(b=>b.onclick=()=>{state.sentenceCenterUnit=b.dataset.sentenceUnit;save();render();});document.querySelectorAll('[data-sentence-track-mode]').forEach(b=>b.onclick=()=>startSession([{wordId:b.dataset.sentenceId,skill:b.dataset.sentenceTrackMode}],'句子巩固','practice',{manual:true}));document.querySelectorAll('[data-custom-learn]').forEach(b=>b.onclick=()=>startCustomLearning(b.dataset.customLearn,b.dataset.mode));$('#tracking-kind')?.addEventListener('change',e=>{if(e.target.value==='sentences'){go('sentence-track');return;}if(e.target.value==='words'){go('track',true,{learningTrack:'regular',filter:'all'});return;}if(e.target.value==='phrases'){phraseRoot.ui.panel='tracker';phraseRoot.ui.filter='all';phraseRoot.ui.tab='all';go('phrases');}});document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{state.selectedUnit=b.dataset.unit;save();render();});$('#scope-select')?.addEventListener('change',e=>{stopAudio();filter=e.target.value;page=0;schedulePage=0;contextCustomPage=0;render();history.replaceState({view,context:routeContext()},'',`#${routeHash(view)}`);});$('#word-search')?.addEventListener('input',e=>{search=e.target.value;page=0;schedulePage=0;contextCustomPage=0;const pos=e.target.selectionStart;render();$('#word-search').focus();$('#word-search').setSelectionRange(pos,pos);});$('#custom-group-filter')?.addEventListener('change',e=>{filter=e.target.value;page=0;render();});$('#skill-filter')?.addEventListener('change',e=>{skillFilter=e.target.value;page=0;render();});$('#sentence-status')?.addEventListener('change',e=>{skillFilter=e.target.value;page=0;render();});$('#show-en')?.addEventListener('change',e=>{showEn=e.target.checked;render();});$('#show-zh')?.addEventListener('change',e=>{showZh=e.target.checked;render();});$('#reading-source')?.addEventListener('change',e=>{stopAudio();readingScope=e.target.value;page=0;render();});$('#passage-select')?.addEventListener('change',e=>{stopAudio();passageIndex=Number(e.target.value);render();});document.querySelectorAll('[data-practice]').forEach(b=>b.addEventListener('click',()=>startSession([{wordId:b.dataset.practice,skill:['preparatory','sentences','custom','reading','cloze','track','sentence-track'].includes(view)?'memory':view==='memory'?'memory':view}],'单词巩固','practice',{manual:true})));document.querySelectorAll('[data-audio-word]').forEach(b=>b.addEventListener('click',()=>playAudio(wordById(b.dataset.audioWord),{assessment:false})));document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>showWordDialog(b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>deleteWord(b.dataset.delete)));document.querySelectorAll('[data-context-word]').forEach(b=>b.addEventListener('click',()=>startSession([{wordId:b.dataset.contextWord,skill:'usage'}],'语境运用','practice',{manual:true})));document.querySelectorAll('[data-action]:not([data-pagination])').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action,b)));}
function action(name,b){const s=state.session,w=currentItem()?wordById(currentItem().wordId):null;switch(name){case 'unit-cycle':startUnitCycle(b.dataset.unitId,b.dataset.unitPart);break;case 'mastered-review':go('mastered-review',true,routeContext());break;case 'mastered-start':startMasteredReview(b.dataset.mode);break;case 'schedule-prev':case 'schedule-next':schedulePage=Math.max(0,schedulePage+(name==='schedule-next'?1:-1));render();history.replaceState({view,context:routeContext()},'',`#${routeHash(view)}`);$('#schedule-panel')?.scrollIntoView?.({block:'start',behavior:'auto'});$('#schedule-panel [data-action="'+name+'"]')?.focus({preventScroll:true});break;case 'sentence-center-nav':go('sentence-center');break;case 'session-replay':replayCompletedSession();break;case 'sentence-track-nav':go('sentence-track');break;case 'sentence-center-review':startSession(due(undefined,sentenceWords(),true).slice(0,10),'句子到期复习');break;case 'sentence-center-start':{const {words}=sentenceCenterSelection(),mode=b.dataset.mode;startSession(words.filter(w=>customLearningSkills(w).includes(mode)).map(w=>({wordId:w.id,skill:mode})),'句子练习 · '+({memory:'记忆',meaning:'翻译',listening:'听辨',dictation:'听写',spelling:'默写'}[mode]||mode),'practice',{manual:true});break;}case 'custom-sentences':openCustomSentences();break;case 'custom-mode':startCustomLearning(null,b.dataset.mode);break;case 'unit-sentence-dictation':state.sentenceDictation??={items:{}};state.sentenceDictation.origin=routeContext();state.sentenceDictation.unitId=b.dataset.unitId;state.sentenceDictation.source='all';state.sentenceDictation.page=0;state.sentenceDictation.cursorByGroup={};delete state.sentenceDictation.completedGroupId;save();go('sentence-dictation',true,{...routeContext(),learningTrack:'regular'});break;case 'review-all':startAllDue(b.dataset.skill||'all');break;case 'pause-review-all':{const origin=s?.origin;if(origin)go(origin.view,true,origin);break;}case 'primary-mode':go(b.dataset.mode,true,{...routeContext(),learningTrack:'primary',filter:'primary-school',search:'',page:0});break;case 'primary-lesson':{const ws=automaticWords(primaryWords()).filter(w=>!learned(w)).slice(0,5);startSession(['study',...BASIC].flatMap(skill=>ws.map(w=>({wordId:w.id,skill}))),'预备单元 · 新课学习','lesson');break;}case 'primary-due':startSession(due(undefined,primaryWords()).slice(0,10),'预备单元 · 到期复习');break;case 'back-parent':backToParent();break;case 'settings':settings();break;case 'tasks-nav':go(learningTrack==='primary'?'preparatory':'tasks');break;case 'track-nav':go(['sentence-track','sentence-center'].includes(s?.origin?.view)||s?.items?.every(i=>wordById(i.wordId)?.customSentence)?'sentence-track':'track',true,s?.origin?.view==='sentence-track'?s.origin:null);break;case 'context-nav':filter='all';go('context');break;case 'custom-context':filter='custom';go('context');break;case 'analysis-nav':analysisParent={view,filter,search,page,showEn,showZh,skillFilter,passageIndex,readingScope,referenceMode};go('analysis');referenceMode=true;render();break;case 'resume':if(s?.remediation){s.remediation.paused=false;save();}go('session',true,s?.origin||null);break;case 'new-lesson':startNewLesson();break;case 'smart-review':startSession(due().slice(0,10),'学前智能复习');break;case 'smart-filter':startSession(due(undefined,currentWords()).slice(0,10),'到期智能复习');break;case 'skill-review':startSession(due(b.dataset.skill,currentWords()).slice(0,10),`${LABELS[b.dataset.skill]} · 到期复习`);break;case 'module-start':startSession(sortedPractice(filteredWords()).slice(0,10).map(w=>({wordId:w.id,skill:view})),view==='memory'?'翻卡记忆':LABELS[view]);break;case 'module-due':startSession(due(view==='memory'?'meaning':view,filteredWords()).slice(0,10),`${view==='memory'?'翻译辨义':LABELS[view]} · 到期复习`);break;case 'mistakes-due':startSession(wrong(skillFilter==='all'?undefined:skillFilter,currentWords()).filter(itemDue).slice(0,10),'到期错词');break;case 'mistakes-all':startSession(wrong(skillFilter==='all'?undefined:skillFilter,currentWords()).slice(0,10),'错词提前巩固');break;case 'next-item':advance();break;case 'context-audio':playContextSentence();break;case 'context-stop':stopAudio();if($('#context-speech-notice'))$('#context-speech-notice').textContent='已停止。';break;case 'audio':if(w)playAudio(w);break;case 'skip':stopAudio();if(s&&!s.result){s.result={skip:true};save();render();}break;case 'reveal':s.revealed=true;save();render();break;case 'rating':if(!s.result){const out=scoreItem(b.dataset.rating);s.result={correct:b.dataset.rating!=='again',...out};state.exposure[w.id]=now()+state.settings.steps[0]*MINUTE;save();render();}break;case 'hint':if(!s.result){s.hint=true;s.hintReason='hint';expose(w);render();}break;case 'retry':stopAudio();s.attemptNo=(s.attemptNo||0)+1;s.result=null;s.draft='';s.revealed=false;s.hint=false;s.hintReason=null;s.practiceOnly=true;listenReady=false;expose(w);render();break;case 'add-word':showWordDialog();break;case 'batch-words':showBatchDialog();break;case 'prev-page':stopAudio();page=Math.max(0,page-1);render();history.replaceState({view,context:routeContext()},'',`#${routeHash(view)}`);break;case 'next-page':stopAudio();page++;render();history.replaceState({view,context:routeContext()},'',`#${routeHash(view)}`);break;case 'context-new-only':referenceMode=false;filter='all';render();break;case 'context-start':referenceMode=false;filter='all';render();break;case 'retry-question':{if(['context','reading','cloze'].includes(view))return;const q=allQuestions().find(q=>q.id===b.dataset.questionId);if(q.wordId)state.exposure[q.wordId]=now()+state.settings.steps[0]*MINUTE;state.dailyQuestionSeen??={};state.dailyQuestionSeen[q.id]=true;delete state.results[q.id];save();render();break;}}}
shortcutController=createControlReplay({isEnabled:()=>view==='sentence-dictation'?!!document.querySelector('[data-sentence-play]')&&!document.hidden&&!document.querySelector('dialog[open]'):view==='phrases'?phraseRuntime?.canReplay():replayEnabled(),getContext:()=>view==='sentence-dictation'?document.querySelector('[data-sentence-play]')?.dataset.sentencePlay:view==='phrases'?phraseRuntime?.key():audioContext(),onReplay:()=>view==='sentence-dictation'?document.querySelector('[data-sentence-play]')?.click():view==='phrases'?phraseRuntime.replay():playAudio(wordById(currentItem().wordId))});
