const accountButton=$('#account-button');if(accountButton){accountButton.textContent='账户 · '+(window.__CIJIAN_ACCOUNT__?.username||'已登录');accountButton.title='查看账户与云端进度';accountButton.addEventListener('click',()=>{settings();requestAnimationFrame(()=>$('#settings-dialog .cloud-sync')?.scrollIntoView({block:'start'}));});}$('#settings-button').addEventListener('click',settings);$('#settings-dialog').addEventListener('close',()=>practiceTimer.setEligible(practiceEligible(view,state,document)));$('.brand').addEventListener('click',e=>{e.preventDefault();go('tasks');});window.addEventListener('popstate',event=>{const route=parseRoute(location.hash.slice(1));go(route.view,false,event.state?.context||route.context);});
