function updatePracticeClock(){const snapshot=practiceTimer.snapshot();if($('#practice-time-button'))$('#practice-time-button').textContent=snapshot.storageAvailable?'今日练习 '+formatPracticeTime(snapshot.todayMs):'练习计时未保存';}
function practiceTimeDetails(dayPage=0){const d=$('#practice-time-dialog'),snapshot=practiceTimer.snapshot(),info=pageSlice(Object.entries(snapshot.days||{}).sort((a,b)=>b[0].localeCompare(a[0])),dayPage,15),controls=paginationHTML(info,{key:'practice-days',label:'按天记录',itemLabel:'天'});d.innerHTML=`<div class="dialog-heading"><h2>有效练习时长</h2><button class="close" id="close-practice-time" aria-label="关闭">×</button></div><p>今天：<strong>${formatPracticeTime(snapshot.todayMs)}</strong></p><p>开始学习后，查看答题结果、站内切换页面、加载和等待都计入最近一次操作后的60秒。连续60秒没有输入、点击或按键会暂停，操作后继续；实际播放练习音频时持续计入。切到其他标签页、后台或离开窗口仍暂停，回到窗口后操作再继续。</p><p class="inline-note">这是按活动估算的有效时间，不能判断是否真正专注；仅从本功能启用后开始；登录云同步后可随其他学习记录保存，不补算过去记录。</p><h3>按天记录</h3>${controls}${info.items.map(([day,ms])=>`<p>${esc(day)} · ${formatPracticeTime(ms)}</p>`).join('')||'<p>还没有已记录的练习时间。</p>'}${controls}`;if(!d.open)d.showModal();bindPagination(d,{onChange:(_,next)=>{practiceTimeDetails(next);focusPagination(d,'practice-days');}});$('#close-practice-time').onclick=()=>d.close();}
$('#practice-time-button')?.addEventListener('click',()=>{stopAudio();practiceTimer.setEligible(false);practiceTimeDetails();});$('#practice-time-dialog')?.addEventListener('close',()=>practiceTimer.setEligible(practiceEligible(view,state,document)));
