function relatedPhraseGroups(entry){const core=entry.english.toLowerCase().replace(/^be /,'').replace(/(?: doing something| to do something| somebody| something| someone)$/,'').trim();if(core.length<5)return [];return ['context','reading','cloze'].map(module=>({module,ids:ADAPTIVE_BANK.questions.filter(q=>q.module===module&&((q.completedPassage||q.passage||q.context||q.prompt||'').replace(/_{2,}/g,q.answer||'').toLowerCase().includes(core))).map(q=>q.id)})).filter(g=>g.ids.length);}
phraseRuntime=createPhraseUI({document,root:phraseRoot,bank:PHRASE_BANK,lookup:lookupEnglish,audio:PHRASE_AUDIO,prepare:file=>player.prefetchFile(file).catch(()=>{}),esc,save:savePhrase,onRender:render,stopAudio,playFile:(file,options)=>player.playFile(file,options),playKokoro:(text,options)=>customKokoro.play(text,options),onFocus:element=>answerFocus.focusEditor(element),onLearningEvent:trackLearning,onWordTracker:()=>go('track'),relatedFor:relatedPhraseGroups,onRelated:(module,ids)=>{phraseRelatedParent=true;const existing=state.adaptive?.modules?.[module]?.session;if(existing&&!existing.complete){phraseRelatedFilter=null;toast('该模块已有未完成的一组，先继续已保存练习。');}else phraseRelatedFilter={module,ids};go(module);},now});
const initialRoute=parseRoute(location.hash.slice(1));view=initialRoute.view==='session'&&!state.session?(initialRoute.context.learningTrack==='primary'?'preparatory':'tasks'):initialRoute.view;restoreRoute(history.state?.context||initialRoute.context);if(view==='session'&&state.session?.origin?.filter==='primary-school'){learningTrack='primary';filter='primary-school';}render();history.replaceState({view,context:routeContext()},'',`#${routeHash(view)}`);
function refreshTimedPage(){
 if(['track','sentence-track'].includes(view)){
  const words=currentWords(),allDue=due(undefined,words),allButton=$('[data-action="review-all"][data-skill="all"]'),quickButton=$('[data-action="smart-filter"]');
  if(allButton){allButton.disabled=!allDue.length;allButton.textContent=`复习全部（${allDue.length}项到期 · 全部能力）`;}
  if(quickButton)quickButton.disabled=!allDue.length;
  document.querySelectorAll('.skill-card').forEach(card=>{const skill=card.querySelector('[data-action="skill-review"]')?.dataset.skill;if(!skill)return;const count=due(skill,words).length;const number=card.querySelector('.big');if(number)number.textContent=String(count);card.querySelectorAll('[data-skill="'+skill+'"]').forEach(control=>control.disabled=!count);});
 }
 if(view==='tasks'){
  const items=due(),control=$('[data-action="smart-review"]'),next=nextTime();if(control){control.disabled=!items.length;control.textContent=items.length?'智能复习':'暂无到期';const copy=control.closest('.task-step')?.querySelector('p');if(copy)copy.textContent=items.length?`${items.length}项能力到期，先练10项。`:next?`下次到期 ${dateTime(next)}`:'学过后会在这里形成复习任务。';}
 }
 if(view==='mistakes'){
  const count=wrong(skillFilter==='all'?undefined:skillFilter,currentWords()).filter(itemDue).length,control=$('[data-action="mistakes-due"]');if(control){control.disabled=!count;control.textContent=`复习到期错词（${count}）`;}
 }
}
